package kinds

// builtinHelp is the help of the fields of the built-in kinds: what the field is, what it is used for, where to get it (and the permissions of a
// token). It is general: no project is named. A project's own help for a field it maps (connections: variables: help) is shown in preference.
var builtinHelp = map[string]Text{
	"aws.access_key_id":     {"en": "The id of an AWS access key (starts with AKIA or ASIA). It identifies the IAM user the tools act as. Get it: AWS console, IAM, Users, the user, Security credentials, Create access key. The user needs the permissions the deployment uses.", "uk": "Ідентифікатор ключа доступу AWS (починається з AKIA або ASIA). Визначає IAM-користувача, від імені якого діють інструменти. Де взяти: консоль AWS, IAM, Users, користувач, Security credentials, Create access key. Користувачу потрібні права, які використовує розгортання.", "ru": "Идентификатор ключа доступа AWS (начинается с AKIA или ASIA). Определяет IAM-пользователя, от имени которого работают инструменты. Где взять: консоль AWS, IAM, Users, пользователь, Security credentials, Create access key. Пользователю нужны права, которые использует развёртывание."},
	"aws.secret_access_key": {"en": "The secret part of the AWS access key; shown once when the key is made, copy it then. Pairs with the access key id.", "uk": "Секретна частина ключа доступу AWS; показується один раз під час створення ключа, скопіюйте її тоді. Працює в парі з ідентифікатором ключа.", "ru": "Секретная часть ключа доступа AWS; показывается один раз при создании ключа, скопируйте её тогда. Работает в паре с идентификатором ключа."},
	"aws.region":            {"en": "The default AWS region of the calls, for example eu-central-1. Get it: the region selector of the AWS console.", "uk": "Типовий регіон AWS для викликів, наприклад eu-central-1. Де взяти: вибір регіону в консолі AWS.", "ru": "Регион AWS по умолчанию для вызовов, например eu-central-1. Где взять: выбор региона в консоли AWS."},
	"aws.account_id":        {"en": "The 12-digit id of the AWS account. Get it: AWS console, the account menu at the top right.", "uk": "12-значний ідентифікатор акаунта AWS. Де взяти: консоль AWS, меню акаунта вгорі праворуч.", "ru": "12-значный идентификатор аккаунта AWS. Где взять: консоль AWS, меню аккаунта вверху справа."},
	"google.project":        {"en": "The id of the Google Cloud project the resources live in (not its display name). Get it: Google Cloud console, the project selector, column ID.", "uk": "Ідентифікатор проєкту Google Cloud, у якому живуть ресурси (не відображувана назва). Де взяти: консоль Google Cloud, вибір проєкту, колонка ID.", "ru": "Идентификатор проекта Google Cloud, в котором живут ресурсы (не отображаемое имя). Где взять: консоль Google Cloud, выбор проекта, колонка ID."},
	"google.credentials":    {"en": "The JSON key file of a service account, kept in the vault as a file. Get it: Google Cloud console, IAM and admin, Service accounts, the account, Keys, Add key, JSON. The account needs the roles the deployment uses.", "uk": "JSON-файл ключа сервісного акаунта, що зберігається в сховищі як файл. Де взяти: консоль Google Cloud, IAM та адміністрування, Service accounts, акаунт, Keys, Add key, JSON. Акаунту потрібні ролі, які використовує розгортання.", "ru": "JSON-файл ключа сервисного аккаунта, хранится в хранилище как файл. Где взять: консоль Google Cloud, IAM и администрирование, Service accounts, аккаунт, Keys, Add key, JSON. Аккаунту нужны роли, которые использует развёртывание."},
	"cloudflare.api_token":  {"en": "A Cloudflare API token. It acts with exactly the permissions it was given, so give it only what the work needs. Get it: Cloudflare dashboard, My Profile, API Tokens, Create Token (shown once). Account-level tokens: Manage Account, Account API Tokens.", "uk": "Токен API Cloudflare. Діє рівно з тими правами, що йому дали, тож давайте лише потрібні для роботи. Де взяти: панель Cloudflare, My Profile, API Tokens, Create Token (показується один раз). Токени рівня акаунта: Manage Account, Account API Tokens.", "ru": "Токен API Cloudflare. Действует ровно с теми правами, что ему дали, поэтому давайте только нужные для работы. Где взять: панель Cloudflare, My Profile, API Tokens, Create Token (показывается один раз). Токены уровня аккаунта: Manage Account, Account API Tokens."},
	"cloudflare.account_id": {"en": "The id of the Cloudflare account. Get it: Cloudflare dashboard, the account, Overview, or the URL after dash.cloudflare.com/.", "uk": "Ідентифікатор акаунта Cloudflare. Де взяти: панель Cloudflare, акаунт, Overview, або адреса після dash.cloudflare.com/.", "ru": "Идентификатор аккаунта Cloudflare. Где взять: панель Cloudflare, аккаунт, Overview, или адрес после dash.cloudflare.com/."},
	"cloudflare.zone_id":    {"en": "The id of one DNS zone (domain) in Cloudflare. Get it: Cloudflare dashboard, the domain, Overview, right column, Zone ID.", "uk": "Ідентифікатор однієї DNS-зони (домену) в Cloudflare. Де взяти: панель Cloudflare, домен, Overview, права колонка, Zone ID.", "ru": "Идентификатор одной DNS-зоны (домена) в Cloudflare. Где взять: панель Cloudflare, домен, Overview, правая колонка, Zone ID."},
	"dockerhub.username":    {"en": "The Docker Hub user (or organisation account) the token belongs to. Get it: hub.docker.com, the account menu.", "uk": "Користувач Docker Hub (або акаунт організації), якому належить токен. Де взяти: hub.docker.com, меню акаунта.", "ru": "Пользователь Docker Hub (или аккаунт организации), которому принадлежит токен. Где взять: hub.docker.com, меню аккаунта."},
	"dockerhub.token":       {"en": "A Docker Hub access token; set its scope (read, write, delete) to what the work needs. Get it: hub.docker.com, Account settings, Personal access tokens, Generate new token (shown once).", "uk": "Токен доступу Docker Hub; виберіть його права (read, write, delete) за потребою. Де взяти: hub.docker.com, Account settings, Personal access tokens, Generate new token (показується один раз).", "ru": "Токен доступа Docker Hub; выберите его права (read, write, delete) по необходимости. Где взять: hub.docker.com, Account settings, Personal access tokens, Generate new token (показывается один раз)."},
	"hcp.organization":      {"en": "The name of the HCP Terraform organization that holds the workspaces and the state. Get it: app.terraform.io, the organization selector.", "uk": "Назва організації HCP Terraform, що тримає робочі простори й стан. Де взяти: app.terraform.io, вибір організації.", "ru": "Название организации HCP Terraform, которая держит рабочие пространства и состояние. Где взять: app.terraform.io, выбор организации."},
	"hcp.token":             {"en": "An HCP Terraform API token (user or team token) allowed to read and write the workspaces of the organization. Get it: app.terraform.io, User settings, Tokens, Create an API token (shown once), or Terraform login.", "uk": "Токен API HCP Terraform (користувача або команди) з правом читати й змінювати робочі простори організації. Де взяти: app.terraform.io, User settings, Tokens, Create an API token (показується один раз), або terraform login.", "ru": "Токен API HCP Terraform (пользователя или команды) с правом читать и менять рабочие пространства организации. Где взять: app.terraform.io, User settings, Tokens, Create an API token (показывается один раз), или terraform login."},
	"s3.bucket":             {"en": "The name of the bucket. Get it: the storage provider console, the bucket list.", "uk": "Назва бакета. Де взяти: консоль постачальника сховища, список бакетів.", "ru": "Название бакета. Где взять: консоль поставщика хранилища, список бакетов."},
	"s3.endpoint":           {"en": "The S3 API address of the provider, for example https://<account>.r2.cloudflarestorage.com. Empty for AWS S3. Get it: the bucket settings of the provider.", "uk": "Адреса S3 API постачальника, наприклад https://<account>.r2.cloudflarestorage.com. Для AWS S3 порожньо. Де взяти: налаштування бакета в постачальника.", "ru": "Адрес S3 API поставщика, например https://<account>.r2.cloudflarestorage.com. Для AWS S3 пусто. Где взять: настройки бакета у поставщика."},
	"s3.region":             {"en": "The region of the bucket (auto for some providers). Get it: the bucket settings of the provider.", "uk": "Регіон бакета (у деяких постачальників auto). Де взяти: налаштування бакета в постачальника.", "ru": "Регион бакета (у некоторых поставщиков auto). Где взять: настройки бакета у поставщика."},
	"s3.prefix":             {"en": "An optional folder (key prefix) inside the bucket; everything is read and written under it. Empty: the bucket root.", "uk": "Необов’язкова папка (префікс ключа) всередині бакета; усе читається й записується під нею. Порожньо: корінь бакета.", "ru": "Необязательная папка (префикс ключа) внутри бакета; всё читается и пишется под ней. Пусто: корень бакета."},
	"s3.access_key_id":      {"en": "The id of the access key of the bucket. Get it: the storage provider console, API tokens or access keys for the bucket; give it only the object permissions the work needs.", "uk": "Ідентифікатор ключа доступу до бакета. Де взяти: консоль постачальника сховища, API-токени або ключі доступу бакета; давайте лише права на об’єкти, потрібні для роботи.", "ru": "Идентификатор ключа доступа к бакету. Где взять: консоль поставщика хранилища, API-токены или ключи доступа бакета; давайте только права на объекты, нужные для работы."},
	"s3.secret_access_key":  {"en": "The secret part of the bucket access key; shown once when the key is made, copy it then.", "uk": "Секретна частина ключа доступу до бакета; показується один раз під час створення ключа, скопіюйте її тоді.", "ru": "Секретная часть ключа доступа к бакету; показывается один раз при создании ключа, скопируйте её тогда."},
}

func init() {
	for i := range connections {
		for j := range connections[i].Fields {
			f := &connections[i].Fields[j]
			f.Help = builtinHelp[connections[i].ID+"."+f.Name]
		}
	}
}
